const sizes = ["sm", "md", "lg"] as const;
const colors = ["primary", "secondary", "success", "info", "warning", "error", "neutral"] as const;

export { sizes as cascaderSizes, colors as cascaderColors };

export default {
  slots: {
    wrapper: "relative inline-flex w-full group outline-none",
    trigger: "",
    triggerText: "truncate text-gray-8 dark:text-gray-1 flex-1",
    placeholder: "truncate text-gray-4 dark:text-gray-5 flex-1",
    dropdown: "!w-auto !overflow-visible !border-transparent !bg-transparent !shadow-none p-0",
    panel: "flex w-max items-start gap-2 bg-transparent p-1",
    column:
      "min-w-[160px] shrink-0 overflow-y-auto rounded-ui-md border border-gray-2 bg-white py-1 min-h-[280px] shadow-lg",
    option:
      "relative flex items-center gap-2 px-3 py-2 text-body-md text-gray-900 cursor-pointer transition-colors hover:bg-gray-1",
    optionActive: "font-medium",
    optionDisabled: "cursor-not-allowed opacity-50 hover:bg-transparent",
    optionLabel: "flex-1 truncate",
    optionIcon: "shrink-0 text-gray-5",
    empty:
      "min-w-[160px] rounded-ui-md border border-gray-2 bg-white px-4 py-6 text-body-md text-gray-5 shadow-lg",
  },
  variants: {
    size: {
      sm: {
        column: "min-w-[140px] max-h-[280px]",
        option: "px-2 py-1.5 text-body-sm",
      },
      md: {
        column: "max-h-[320px]",
      },
      lg: {
        column: "min-w-[180px] max-h-[360px]",
        option: "px-4 py-2.5 text-body-lg",
      },
    },
    color: {
      primary: {
        optionActive: "bg-primary/10 text-primary",
      },
      secondary: {
        optionActive: "bg-secondary/10 text-secondary",
      },
      success: {
        optionActive: "bg-success/10 text-success",
      },
      info: {
        optionActive: "bg-info/10 text-info",
      },
      warning: {
        optionActive: "bg-warning/10 text-warning",
      },
      error: {
        optionActive: "bg-error/10 text-error",
      },
      neutral: {
        optionActive: "bg-neutral/10 text-neutral",
      },
    },
    disabled: {
      true: {},
    },
  },
  compoundVariants: [
    { size: "sm", class: { dropdown: "min-w-0" } },
    { size: "md", class: { dropdown: "min-w-0" } },
    { size: "lg", class: { dropdown: "min-w-0" } },
  ] as any,
  defaultVariants: {
    size: "md" as (typeof sizes)[number],
    color: "primary" as (typeof colors)[number],
  },
};

export const CascaderSizes = ['sm', 'md', 'lg'] as const
export const CascaderColors = ['primary', 'secondary', 'success', 'info', 'warning', 'error', 'neutral'] as const

export type CascaderSize = (typeof CascaderSizes)[number]
export type CascaderColor = (typeof CascaderColors)[number]

export interface CascaderUI {
    root?: string
    popup?: string
    tabsScroll?: string
    tabs?: string
    tab?: string
    tabActive?: string
    list?: string
    item?: string
    itemActive?: string
    itemText?: string
    itemTextActive?: string
    footer?: string
    footerText?: string
    loading?: string
    loadingText?: string
    listScroll?: string
    listInner?: string
    column?: string
    columnScroll?: string
    itemInner?: string
    checkbox?: string
    nodeLoading?: string
    nodeArrow?: string
    footerActions?: string
}

// 选项接口定义
export interface CascaderOption {
    label: string
    value: string | number
    children?: CascaderOption[]
    [key: string]: any
}

export interface CascaderProps {
    /** 绑定值 */
    modelValue?: (string | number)[] | (string | number)[][]
    /** 选项数据 */
    options?: CascaderOption[]
    /** 标题 */
    title?: string
    /** 占位提示 */
    placeholder?: string
    /** 是否显示触发器 */
    showTrigger?: boolean
    /** 是否禁用 */
    disabled?: boolean
    /** 标签字段 */
    labelKey?: string
    /** 值字段 */
    valueKey?: string
    /** 分隔符 */
    textSeparator?: string
    /** 列表高度 (rpx) */
    height?: number | string
    /** 尺寸 */
    size?: CascaderSize
    /** 颜色 */
    color?: CascaderColor
    /** 自定义类名 */
    customClass?: string
    /** 自定义样式 */
    customStyle?: string
    /** UI 覆盖 */
    ui?: CascaderUI
    /** 是否动态加载子节点 */
    lazy?: boolean
    /** 加载动态数据的方法 */
    lazyLoad?: (node: CascaderOption, resolve: (children: CascaderOption[]) => void, reject: () => void) => void
    /** 指定选项的子选项字段 */
    childrenKey?: string
    /** 查询次级菜单层级；为0时候查询所有 */
    leafLevel?: number
    /** 是否多选 */
    multiple?: boolean
    /** 是否显示省略号 */
    ellipsis?: boolean
    /** 省略号行数 */
    lines?: number
}

const config = {
    slots: {
        root: 'w-full',
        popup: 'bg-white dark:bg-slate-900 rounded-t-[32rpx] overflow-hidden',
        tabsScroll: 'w-full border-b border-gray-100 dark:border-slate-800 no-scrollbar',
        tabs: 'flex flex-row items-center p-2 gap-1.5',
        tab: 'reborn-cascader-tab shrink-0 text-28 [.reborn-cascader-tab_+_&]:ml-1',
        tabActive: '',
        list: 'h-[600rpx]',
        item: 'flex flex-row items-center justify-between px-[32rpx] py-[24rpx] active:bg-gray-50 dark:active:bg-slate-800 transition-colors',
        itemActive: 'bg-primary/5 dark:bg-primary/10',
        itemText: 'text-[28rpx]',
        itemTextActive: 'text-primary font-medium',
        footer: 'flex flex-row items-center justify-between px-[32rpx] py-[24rpx] border-t border-gray-100 dark:border-slate-800',
        footerText: 'text-[24rpx] text-gray-500',
        loading: 'flex flex-col items-center justify-center h-full w-full',
        loadingText: 'mt-2 text-[24rpx] text-gray-400',
        listScroll: 'w-full h-full no-scrollbar',
        listInner: 'flex flex-row h-full min-w-full',
        column: 'shrink-0 h-full border-r border-gray-100 dark:border-slate-800 last:border-r-0',
        columnScroll: 'h-full',
        itemInner: 'flex flex-row items-center',
        checkbox: 'mr-2',
        nodeLoading: 'ml-auto h-[32rpx] w-[32rpx]',
        nodeArrow: 'i-lucide-chevron-right text-[32rpx] text-gray-300 ml-auto',
        footerActions: 'flex flex-row gap-2',
    },
    variants: {
        size: {
            sm: {
                tab: 'text-26',
                item: 'h-input-sm',
                itemText: 'text-26',
            },
            md: {
                item: 'h-input-md',
                itemText: 'text-28',
            },
            lg: {
                item: 'h-input-lg',
                itemText: 'text-28',
            },
        },
        color: {
            primary: {
                itemTextActive: 'text-primary',
                itemActive: 'bg-primary/5',
            },
            secondary: {
                itemTextActive: 'text-secondary',
                itemActive: 'bg-secondary/5',
            },
            success: {
                itemTextActive: 'text-success',
                itemActive: 'bg-success/5',
            },
            info: {
                itemTextActive: 'text-info',
                itemActive: 'bg-info/5',
            },
            warning: {
                itemTextActive: 'text-warning',
                itemActive: 'bg-warning/5',
            },
            error: {
                itemTextActive: 'text-error',
                itemActive: 'bg-error/5',
            },
            neutral: {
                itemTextActive: 'text-slate-900 dark:text-white',
                itemActive: 'bg-slate-100 dark:bg-slate-800',
            },
        },
    },
    defaultVariants: {
        color: 'primary',
        size: 'md',
    },
} as const

export default config
